	@Test
	public void testTripleFunctionInProjectionEvaluatesExpressionArguments() {
		var vf = testCon.getValueFactory();
		var subject = vf.createBNode("triple-expression-subject");
		var object = vf.createLiteral("Bob");
		testCon.add(subject, FOAF.NAME, object);

		String query = "PREFIX foaf: <" + FOAF.NAMESPACE + ">"
				+ " SELECT ?s (IF(true, TRIPLE(?s, foaf:name, STR(?o)), 42) AS ?t)"
				+ " WHERE { ?s foaf:name ?o }";
		List<BindingSet> result = QueryResults.asList(testCon.prepareTupleQuery(query).evaluate());

		assertThat(result).hasSize(1);
		assertThat(result.get(0).getValue("t")).isEqualTo(vf.createTripleTerm(subject, FOAF.NAME, object));
	}

